-- DRAFT, NOT EXECUTED, NO PASSWORD. OPTIONAL: a separate read-only login for the OKX Paper Manager. The recommended path needs NO database change at all:
-- the existing login ts_portal_manager_read_facade (NOINHERIT, connlimit 12, member of the group role ts_portal_manager_read) already has a pg_hba line for trading_system
-- (hostssl, 172.18.0.0/16, scram-sha-256: line 100 on 2026-11-18) and the group role already has SELECT on all 67 relations and on public.schema_migration_ledger
-- (read-only check 2026-11-18: 67/67 can_select, 0 can_write; ledger can_select true). The new Manager container sits on executor_network (172.18.0.0/16) like the Paper one.
-- Use this file only if the owner wants a login of its own (so the OKX pool cannot take connections from the Paper pool). It follows the Sandbox pattern
-- (sandbox_manager_roles_grants.DRAFT.sql); the password is generated by the host step and goes only to the 0600 DSN file.
CREATE ROLE ts_portal_manager_read_okx_facade LOGIN NOINHERIT CONNECTION LIMIT 4 PASSWORD '<host step: secret file, never in this file>';
GRANT ts_portal_manager_read TO ts_portal_manager_read_okx_facade;
ALTER ROLE ts_portal_manager_read_okx_facade SET default_transaction_read_only = on;
ALTER ROLE ts_portal_manager_read_okx_facade SET statement_timeout = '5000ms';
ALTER ROLE ts_portal_manager_read_okx_facade SET lock_timeout = '1000ms';
ALTER ROLE ts_portal_manager_read_okx_facade SET idle_in_transaction_session_timeout = '10000ms';
GRANT CONNECT ON DATABASE trading_system TO ts_portal_manager_read_okx_facade;   -- harmless if PUBLIC already has it
-- pg_hba (host step, not SQL), inserted BEFORE the line `host trading_system all all reject` (line 106 on 2026-11-18), same method as line 100, restricted to the login:
--   hostssl  trading_system  ts_portal_manager_read_okx_facade  172.18.0.0/16  scram-sha-256
-- then SELECT pg_reload_conf(). The DSN then names the new login instead of ts_portal_manager_read_facade (okx_render.py dsn would need its login check changed).
-- Read-only verification (after):
SELECT rolname, rolconnlimit, rolcanlogin, rolconfig FROM pg_roles WHERE rolname IN ('ts_portal_manager_read', 'ts_portal_manager_read_facade', 'ts_portal_manager_read_okx_facade');
SELECT line_number, type, database, user_name, address, auth_method FROM pg_hba_file_rules WHERE user_name::text LIKE '%okx%';
-- Rollback: DROP ROLE ts_portal_manager_read_okx_facade (after the Manager stopped using it); restore the pg_hba backup taken by the host step; pg_reload_conf().
